-- Full BAS extends reporting without changing any previously frozen Simpler BAS report.
ALTER TABLE accounting.bas_periods DROP CONSTRAINT bas_periods_reporting_method_check;
ALTER TABLE accounting.bas_periods ADD CONSTRAINT bas_periods_reporting_method_check CHECK(reporting_method IN('SIMPLER','FULL'));
ALTER TABLE accounting.bas_periods ADD COLUMN calculation_method text NOT NULL DEFAULT 'ACCOUNTS' CHECK(calculation_method IN('ACCOUNTS','WORKSHEET'));
ALTER TABLE accounting.bas_periods ADD CONSTRAINT bas_method_choice CHECK(reporting_method='FULL' OR calculation_method='ACCOUNTS');
ALTER TABLE accounting.bas_period_controls ADD COLUMN reporting_method text,ADD COLUMN calculation_method text;
ALTER TABLE accounting.bas_period_controls ADD CONSTRAINT bas_control_method CHECK((reporting_method IS NULL AND calculation_method IS NULL)OR(reporting_method IS NOT NULL AND calculation_method IS NOT NULL AND reporting_method IN('SIMPLER','FULL')AND calculation_method IN('ACCOUNTS','WORKSHEET')AND(reporting_method='FULL'OR calculation_method='ACCOUNTS')));
CREATE TABLE accounting.bas_method_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),period_id uuid NOT NULL,version bigint NOT NULL CHECK(version>1),previous_reporting_method text NOT NULL,previous_calculation_method text NOT NULL,reporting_method text NOT NULL CHECK(reporting_method IN('SIMPLER','FULL')),calculation_method text NOT NULL CHECK(calculation_method IN('ACCOUNTS','WORKSHEET')),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),previous_snapshot_id uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,period_id,version),FOREIGN KEY(company_id,period_id)REFERENCES accounting.bas_periods(company_id,id),FOREIGN KEY(company_id,period_id,previous_snapshot_id)REFERENCES accounting.bas_snapshots(company_id,period_id,id),CHECK(reporting_method='FULL'OR calculation_method='ACCOUNTS'));
ALTER TABLE accounting.bas_method_changes ENABLE ROW LEVEL SECURITY;ALTER TABLE accounting.bas_method_changes FORCE ROW LEVEL SECURITY;
CREATE POLICY company_scope ON accounting.bas_method_changes USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company());
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.bas_method_changes FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
CREATE VIEW accounting.bas_effective_periods WITH(security_invoker=true) AS SELECT p.id,p.company_id,p.reference,p.from_date,p.to_date,p.cadence,p.gst_basis,coalesce(k.reporting_method,p.reporting_method)AS reporting_method,p.registration_confirmed,p.due_on,p.created_at,p.created_by,coalesce(k.calculation_method,p.calculation_method)AS calculation_method FROM accounting.bas_periods p JOIN accounting.bas_period_controls k ON k.company_id=p.company_id AND k.id=p.id;
CREATE FUNCTION accounting.bas_change_method(p_id uuid,p_version bigint,p_reporting text,p_calculation text,p_reason text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();p accounting.bas_periods;k accounting.bas_period_controls;BEGIN
 PERFORM accounting.bas_require_access('accounting.bas.manage');PERFORM accounting.bas_lock(c,true);SELECT*INTO p FROM accounting.bas_effective_periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'BAS period unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO k FROM accounting.bas_period_controls WHERE company_id=c AND id=p_id FOR UPDATE;
 IF k.version IS DISTINCT FROM p_version OR k.state<>'OPEN' THEN RAISE EXCEPTION 'Current open BAS period required' USING ERRCODE='HR409';END IF;
 IF p_reporting IS NULL OR p_calculation IS NULL OR p_reporting NOT IN('SIMPLER','FULL') OR p_calculation NOT IN('ACCOUNTS','WORKSHEET')OR(p_reporting='SIMPLER'AND p_calculation<>'ACCOUNTS')OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid BAS method or reason' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.bas_method_changes(company_id,period_id,version,previous_reporting_method,previous_calculation_method,reporting_method,calculation_method,reason,previous_snapshot_id,created_by)VALUES(c,p_id,k.version+1,p.reporting_method,p.calculation_method,p_reporting,p_calculation,btrim(p_reason),k.current_snapshot_id,core.current_actor());
 UPDATE accounting.bas_period_controls SET reporting_method=p_reporting,calculation_method=p_calculation WHERE company_id=c AND id=p_id;
 END $$;
CREATE TABLE accounting.bas_classifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),target_kind text NOT NULL CHECK(target_kind IN('TAX_CODE','EXPENSE_ACCOUNT','BILL_LINE')),target_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),sales_class text NOT NULL CHECK(sales_class IN('AUTO','TAXABLE','EXPORT','OTHER_GST_FREE','INPUT_TAXED','EXCLUDED')),purchase_class text NOT NULL CHECK(purchase_class IN('AUTO','CAPITAL','NON_CAPITAL','EXCLUDED')),input_taxed_percent numeric(7,4) CHECK(input_taxed_percent BETWEEN 0 AND 100),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,target_kind,target_id,revision),CHECK((target_kind='TAX_CODE' AND purchase_class='AUTO' AND input_taxed_percent IS NULL)OR(target_kind<>'TAX_CODE' AND sales_class='AUTO')));
ALTER TABLE accounting.bas_classifications ENABLE ROW LEVEL SECURITY;ALTER TABLE accounting.bas_classifications FORCE ROW LEVEL SECURITY;
CREATE POLICY company_scope ON accounting.bas_classifications USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company());
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.bas_classifications FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
CREATE VIEW accounting.bas_latest_classifications WITH(security_invoker=true) AS SELECT DISTINCT ON(company_id,target_kind,target_id)* FROM accounting.bas_classifications ORDER BY company_id,target_kind,target_id,revision DESC;
INSERT INTO identity.permissions(code,description)VALUES('accounting.bas.classify','Classify Full BAS sales, purchases and non-creditable purpose');
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_bas_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION accounting.bas_classify(p_kind text,p_target uuid,p_version bigint,p_sales text,p_purchase text,p_percent numeric,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();v bigint;t text;result uuid;BEGIN
 PERFORM accounting.bas_require_access('accounting.bas.classify');PERFORM accounting.bas_lock(c,true);
 IF p_kind NOT IN('TAX_CODE','EXPENSE_ACCOUNT','BILL_LINE') OR p_kind IS NULL THEN RAISE EXCEPTION 'Invalid classification target' USING ERRCODE='HR422';END IF;
 IF p_kind='TAX_CODE' THEN SELECT category INTO t FROM accounting.tax_codes WHERE company_id=c AND id=p_target;
 ELSIF p_kind='EXPENSE_ACCOUNT' THEN SELECT kind INTO t FROM accounting.accounts WHERE company_id=c AND id=p_target AND kind='EXPENSE' AND control_kind IS NULL;
 ELSE SELECT 'BILL_LINE' INTO t FROM purchase.bill_lines WHERE company_id=c AND id=p_target;END IF;
 IF t IS NULL THEN RAISE EXCEPTION 'Classification target unavailable' USING ERRCODE='HT404';END IF;
 IF p_sales IS NULL OR p_sales NOT IN('AUTO','TAXABLE','EXPORT','OTHER_GST_FREE','INPUT_TAXED','EXCLUDED') OR p_purchase IS NULL OR p_purchase NOT IN('AUTO','CAPITAL','NON_CAPITAL','EXCLUDED') OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR(p_percent IS NOT NULL AND(p_percent<0 OR p_percent>100 OR p_percent<>round(p_percent,4))) OR(p_kind='TAX_CODE' AND(p_purchase<>'AUTO' OR p_percent IS NOT NULL OR(p_sales<>'AUTO' AND NOT((t='TAXABLE' AND p_sales='TAXABLE') OR(t='GST_FREE' AND p_sales IN('EXPORT','OTHER_GST_FREE')) OR(t='INPUT_TAXED' AND p_sales='INPUT_TAXED') OR(t='OUT_OF_SCOPE' AND p_sales='EXCLUDED'))))) OR(p_kind<>'TAX_CODE' AND p_sales<>'AUTO') THEN RAISE EXCEPTION 'Classification incompatible with source tax category or invalid purpose split' USING ERRCODE='HR422';END IF;
 SELECT coalesce(max(revision),0) INTO v FROM accounting.bas_classifications WHERE company_id=c AND target_kind=p_kind AND target_id=p_target;IF p_version IS DISTINCT FROM v THEN RAISE EXCEPTION 'Classification revision changed' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bas_classifications(company_id,target_kind,target_id,revision,sales_class,purchase_class,input_taxed_percent,reason,created_by)VALUES(c,p_kind,p_target,v+1,p_sales,p_purchase,p_percent,btrim(p_reason),core.current_actor())RETURNING id INTO result;RETURN result;END $$;
CREATE FUNCTION accounting.bas_sales_class(p_code uuid) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT CASE WHEN t.category='TAXABLE' AND coalesce(p.sales_class,'AUTO') IN('AUTO','TAXABLE') THEN 'TAXABLE' WHEN t.category='GST_FREE' AND p.sales_class IN('EXPORT','OTHER_GST_FREE') THEN p.sales_class WHEN t.category='INPUT_TAXED' AND coalesce(p.sales_class,'AUTO') IN('AUTO','INPUT_TAXED') THEN 'INPUT_TAXED' WHEN t.category='OUT_OF_SCOPE' AND coalesce(p.sales_class,'AUTO') IN('AUTO','EXCLUDED') THEN 'EXCLUDED' ELSE 'PENDING' END FROM accounting.tax_codes t LEFT JOIN accounting.bas_latest_classifications p ON p.company_id=t.company_id AND p.target_kind='TAX_CODE' AND p.target_id=t.id WHERE t.company_id=core.current_company() AND t.id=p_code
 $$;
CREATE VIEW accounting.bas_purchase_profiles WITH(security_invoker=true) AS
 SELECT l.company_id,l.id AS bill_line_id,l.bill_id,l.tax_code_id,l.net,l.tax,l.net+l.tax AS gross,l.recoverable_tax,g.gst_basis,g.attribution_date,b.invoice_date,b.tax_invoice_held_on,
 coalesce(nullif(lp.purchase_class,'AUTO'),nullif(ap.purchase_class,'AUTO'),CASE WHEN rl.item_type='STOCK' THEN 'NON_CAPITAL' ELSE 'PENDING' END)AS purchase_class,
 coalesce(lp.input_taxed_percent,ap.input_taxed_percent)AS input_taxed_percent,
 coalesce(lp.id,ap.id)AS classification_id,coalesce(lp.revision,ap.revision,0)AS classification_revision
 FROM purchase.bill_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.id
 LEFT JOIN purchase.receipt_lines rr ON rr.company_id=l.company_id AND rr.id=l.receipt_line_id LEFT JOIN purchase.order_lines rl ON rl.company_id=rr.company_id AND rl.id=rr.order_line_id
 LEFT JOIN accounting.bas_latest_classifications lp ON lp.company_id=l.company_id AND lp.target_kind='BILL_LINE' AND lp.target_id=l.id
 LEFT JOIN accounting.bas_latest_classifications ap ON ap.company_id=l.company_id AND ap.target_kind='EXPENSE_ACCOUNT' AND ap.target_id=l.expense_account_id;
CREATE FUNCTION accounting.bas_worksheet_positions(on_date date) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH invoice_totals AS MATERIALIZED(SELECT l.order_line_id,sum(l.gross) AS billed_all,coalesce(sum(l.gross)FILTER(WHERE i.gst_basis='NON_CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)),0) AS billed_nc FROM sales.invoice_lines l JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id WHERE l.company_id=core.current_company() AND i.invoice_date<=on_date GROUP BY l.order_line_id),
 triggered AS MATERIALIZED(SELECT DISTINCT a.order_line_id FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN core.companies c ON c.id=a.company_id WHERE a.company_id=core.current_company() AND a.gst_basis='NON_CASH' AND c.gst_registered AND r.received_on<=on_date AND NOT EXISTS(SELECT 1 FROM accounting.receipt_reversals v JOIN platform.documents d ON d.company_id=v.company_id AND d.id=v.id WHERE v.company_id=a.company_id AND v.receipt_id=r.id AND d.business_date<=on_date)),
 cancelled AS MATERIALIZED(SELECT l.order_line_id,sum(l.cancelled_gross) AS amount FROM inventory.sales_return_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.return_id WHERE l.company_id=core.current_company() AND l.invoice_line_id IS NULL AND d.business_date<=on_date GROUP BY l.order_line_id),
 credited AS MATERIALIZED(SELECT il.order_line_id,sum(cl.gross) AS amount FROM sales.credit_note_lines cl JOIN sales.invoice_lines il ON il.company_id=cl.company_id AND il.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id JOIN platform.documents d ON d.company_id=cl.company_id AND d.id=cl.credit_note_id WHERE cl.company_id=core.current_company() AND i.gst_basis='NON_CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false) AND d.business_date<=on_date GROUP BY il.order_line_id)
 SELECT l.company_id,'NON_CASH_ORDER'::text,l.id,l.order_id,coalesce((SELECT il.tax_code_id FROM sales.invoice_lines il WHERE il.company_id=l.company_id AND il.order_line_id=l.id ORDER BY il.id LIMIT 1),(SELECT a.tax_code_id FROM accounting.customer_advances a WHERE a.company_id=l.company_id AND a.order_line_id=l.id ORDER BY a.id LIMIT 1),tc.id),
 coalesce(i.billed_nc,0)+CASE WHEN tr.order_line_id IS NOT NULL THEN greatest(0,l.gross-coalesce(i.billed_all,0)) ELSE 0 END
 FROM sales.order_lines l JOIN sales.orders o ON o.company_id=l.company_id AND o.id=l.order_id JOIN core.companies c ON c.id=l.company_id LEFT JOIN invoice_totals i ON i.order_line_id=l.id LEFT JOIN triggered tr ON tr.order_line_id=l.id LEFT JOIN cancelled ca ON ca.order_line_id=l.id LEFT JOIN credited cr ON cr.order_line_id=l.id LEFT JOIN accounting.tax_codes tc ON tc.company_id=l.company_id AND tc.code=l.snapshot->>'taxCode' WHERE l.company_id=core.current_company() AND(i.order_line_id IS NOT NULL OR tr.order_line_id IS NOT NULL OR cr.order_line_id IS NOT NULL)
 $$;
CREATE FUNCTION accounting.bas_full_sales(p_from date,p_to date,p_worksheet boolean) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,gst_basis text,event_date date,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT * FROM accounting.bas_turnover(p_from,p_to) WHERE NOT p_worksheet
 UNION ALL SELECT x.company_id,x.source_type,x.source_id,x.source_document_id,'CASH',x.event_date,x.tax_code_id,x.gross_amount FROM accounting.bas_cash_sales x WHERE p_worksheet AND x.company_id=core.current_company() AND x.event_date>=p_from AND x.event_date<p_to AND x.source_type NOT IN('CASH_CREDIT_REFUND','CASH_ADVANCE_REFUND','CASH_CREDIT_REFUND_REVERSAL','CASH_ADVANCE_REFUND_REVERSAL','CASH_CREDIT_APPLICATION_SOURCE','CASH_CREDIT_UNAPPLICATION_SOURCE')
 UNION ALL SELECT coalesce(c.company_id,o.company_id),'NON_CASH_WORKSHEET_CHANGE',coalesce(c.source_id,o.source_id),coalesce(c.source_document_id,o.source_document_id),'NON_CASH',p_to-1,coalesce(c.tax_code_id,o.tax_code_id),coalesce(c.gross_amount,0)-coalesce(o.gross_amount,0) FROM accounting.bas_worksheet_positions(p_to-1)c FULL JOIN accounting.bas_worksheet_positions(p_from-1)o ON o.company_id=c.company_id AND o.source_id=c.source_id WHERE p_worksheet AND coalesce(c.gross_amount,0)<>coalesce(o.gross_amount,0)
 $$;
CREATE VIEW accounting.bas_purchase_gross_events WITH(security_invoker=true) AS
 SELECT l.company_id,'NON_CASH_BILL'::text AS source_type,l.id AS source_id,l.id AS bill_line_id,l.bill_id AS source_document_id,coalesce(g.attribution_date,b.invoice_date) AS event_date,l.net+l.tax AS gross_amount,false AS legal_adjustment FROM purchase.bill_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.id WHERE b.gst_basis='NON_CASH'
 UNION ALL SELECT l.company_id,'NON_CASH_CREDIT',l.id,l.bill_line_id,l.credit_note_id,d.business_date,-l.gross,true FROM purchase.supplier_credit_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=l.company_id AND id=l.bill_line_id)JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.credit_note_id WHERE b.gst_basis='NON_CASH'
 UNION ALL SELECT x.company_id,'CASH_ALLOCATION',x.id,x.bill_line_id,x.source_document_id,g.attribution_date,x.amount,false FROM accounting.supplier_payment_allocations x JOIN accounting.purchase_gst_attributions g ON g.company_id=x.company_id AND g.allocation_id=x.id
 UNION ALL SELECT x.company_id,'CASH_PAYMENT_REVERSAL',a.id,a.bill_line_id,x.id,d.business_date,-a.amount,false FROM accounting.supplier_payment_reversals x JOIN accounting.supplier_payment_allocations a ON a.company_id=x.company_id AND a.payment_id=x.payment_id AND a.advance_id IS NULL JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=a.bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_ADVANCE_UNAPPLICATION',a.id,a.bill_line_id,x.id,d.business_date,-a.amount,false FROM accounting.supplier_advance_unapplications x JOIN accounting.supplier_payment_allocations a ON a.company_id=x.company_id AND a.source_document_id=x.application_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=a.bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_REFUND',x.id,cl.bill_line_id,x.id,x.received_on,-x.amount,true FROM accounting.supplier_refunds x JOIN purchase.supplier_credit_lines cl ON cl.company_id=x.company_id AND cl.id=x.credit_line_id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=cl.bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_REFUND_REVERSAL',x.id,cl.bill_line_id,x.id,d.business_date,rf.amount,true FROM accounting.supplier_refund_reversals x JOIN accounting.supplier_refunds rf ON rf.company_id=x.company_id AND rf.id=x.refund_id JOIN purchase.supplier_credit_lines cl ON cl.company_id=rf.company_id AND cl.id=rf.credit_line_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=cl.bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_APPLICATION_SOURCE',x.id,x.source_bill_line_id,x.application_id,d.business_date,-1*x.amount,true FROM purchase.credit_application_lines x JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=x.source_bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_SOURCE',a.id,a.source_bill_line_id,x.id,d.business_date,1*a.amount,true FROM purchase.credit_unapplications x JOIN purchase.credit_application_lines a ON a.company_id=x.company_id AND a.application_id=x.application_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=a.source_bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_APPLICATION_TARGET',x.id,x.target_bill_line_id,x.application_id,d.business_date,1*x.amount,false FROM purchase.credit_application_lines x JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=x.target_bill_line_id) WHERE b.gst_basis='CASH'
 UNION ALL SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_TARGET',a.id,a.target_bill_line_id,x.id,d.business_date,-1*a.amount,false FROM purchase.credit_unapplications x JOIN purchase.credit_application_lines a ON a.company_id=x.company_id AND a.application_id=x.application_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN purchase.bills b ON b.company_id=x.company_id AND b.id=(SELECT bill_id FROM purchase.bill_lines WHERE company_id=x.company_id AND id=a.target_bill_line_id) WHERE b.gst_basis='CASH';
CREATE VIEW accounting.bas_full_tax_events WITH(security_invoker=true) AS
 SELECT e.*,CASE WHEN e.source_type<>'SALES_ADJUSTMENT' AND e.source_type<>'PURCHASE_ADJUSTMENT' THEN false
 WHEN e.side='SALES' AND e.kind IN('RECEIPT_REVERSAL','ADVANCE_UNAPPLICATION') THEN false
 WHEN e.side='PURCHASES' AND e.kind IN('SUPPLIER_PAYMENT_REVERSAL','SUPPLIER_ADVANCE_UNAPPLICATION') THEN false
 WHEN e.side='SALES' AND e.kind='CREDIT_APPLICATION' THEN EXISTS(SELECT 1 FROM sales.credit_application_lines l JOIN accounting.gst_adjustments a ON a.company_id=l.company_id AND a.id=e.source_id WHERE l.company_id=e.company_id AND l.application_id=e.source_document_id AND l.source_invoice_line_id=a.invoice_line_id)
 WHEN e.side='SALES' AND e.kind='CREDIT_UNAPPLICATION' THEN EXISTS(SELECT 1 FROM sales.credit_unapplications u JOIN sales.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id JOIN accounting.gst_adjustments a ON a.company_id=l.company_id AND a.id=e.source_id WHERE u.company_id=e.company_id AND u.id=e.source_document_id AND l.source_invoice_line_id=a.invoice_line_id)
 WHEN e.side='PURCHASES' AND e.kind='CREDIT_APPLICATION' THEN EXISTS(SELECT 1 FROM purchase.credit_application_lines l JOIN accounting.purchase_gst_adjustments a ON a.company_id=l.company_id AND a.id=e.source_id WHERE l.company_id=e.company_id AND l.application_id=e.source_document_id AND l.source_bill_line_id=a.bill_line_id)
 WHEN e.side='PURCHASES' AND e.kind='CREDIT_UNAPPLICATION' THEN EXISTS(SELECT 1 FROM purchase.credit_unapplications u JOIN purchase.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id JOIN accounting.purchase_gst_adjustments a ON a.company_id=l.company_id AND a.id=e.source_id WHERE u.company_id=e.company_id AND u.id=e.source_document_id AND l.source_bill_line_id=a.bill_line_id)
 ELSE true END AS legal_adjustment FROM accounting.bas_tax_events e;
CREATE FUNCTION accounting.bas_full_purchase_items(p_from date,p_to date,p_worksheet boolean) RETURNS TABLE(source_type text,source_id uuid,source_document_id uuid,event_date date,bill_line_id uuid,gst_basis text,tax_code_id uuid,purchase_class text,classification_id uuid,classification_revision bigint,gross_amount numeric,g13 numeric,g14 numeric,g15 numeric,issue boolean) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT e.source_type,e.source_id,e.source_document_id,e.event_date,p.bill_line_id,p.gst_basis,p.tax_code_id,p.purchase_class,p.classification_id,p.classification_revision,e.gross_amount,
 CASE WHEN p.tax>0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount*(p.tax-p.recoverable_tax)/p.tax*coalesce(p.input_taxed_percent,0)/100 ELSE 0 END,
 CASE WHEN p.tax=0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount ELSE 0 END,
 CASE WHEN p.tax>0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount*(p.tax-p.recoverable_tax)/p.tax*(1-coalesce(p.input_taxed_percent,0)/100) ELSE 0 END,
 p.purchase_class='PENDING' OR(p.purchase_class='EXCLUDED' AND p.recoverable_tax>0) OR(p.purchase_class<>'EXCLUDED' AND p.tax>p.recoverable_tax AND p.input_taxed_percent IS NULL)
 FROM accounting.bas_purchase_gross_events e JOIN accounting.bas_purchase_profiles p ON p.company_id=e.company_id AND p.bill_line_id=e.bill_line_id WHERE e.company_id=core.current_company() AND e.event_date>=p_from AND e.event_date<p_to AND(NOT p_worksheet OR NOT e.legal_adjustment)
 $$;

-- Independent purchase control comes from historical AP movements, not the new reporting-event union.
CREATE FUNCTION accounting.bas_purchase_reference(p_from date,p_to date) RETURNS numeric LANGUAGE sql STABLE SET search_path=pg_catalog SET jit=off AS $$
 WITH movements AS MATERIALIZED(SELECT * FROM accounting.report_open_item_movements WHERE company_id=core.current_company() AND side='AP'),
 dated AS MATERIALIZED(SELECT CASE WHEN b.gst_basis='NON_CASH' THEN m.amount ELSE -m.amount END AS amount,
 CASE WHEN b.gst_basis='NON_CASH' AND d.document_type='SUPPLIER_BILL' THEN coalesce(g.attribution_date,b.invoice_date) WHEN b.gst_basis='CASH' THEN coalesce((SELECT min(attribution_date) FROM accounting.purchase_gst_attributions WHERE company_id=m.company_id AND source_document_id=m.source_document_id AND bill_line_id=m.item_line_id),d.business_date) ELSE d.business_date END AS event_date
 FROM movements m JOIN purchase.bill_lines l ON l.company_id=m.company_id AND l.id=m.item_line_id JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN platform.documents d ON d.company_id=m.company_id AND d.id=m.source_document_id LEFT JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.id
 WHERE(b.gst_basis='NON_CASH' AND d.document_type IN('SUPPLIER_BILL','SUPPLIER_CREDIT'))OR(b.gst_basis='CASH' AND d.document_type NOT IN('SUPPLIER_BILL','SUPPLIER_CREDIT')))
 SELECT coalesce(sum(amount),0) FROM dated WHERE event_date>=p_from AND event_date<p_to
 $$;
CREATE FUNCTION accounting.bas_full_summary_raw(p_from date,p_to date,p_method text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH base AS MATERIALIZED(SELECT accounting.bas_summary(p_from,p_to)AS report),
 sales AS MATERIALIZED(SELECT w AS worksheet,x.*,coalesce(accounting.bas_sales_class(x.tax_code_id),'PENDING')AS classification FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_sales(p_from,p_to,w)x),
 purchases AS MATERIALIZED(SELECT w AS worksheet,x.* FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_purchase_items(p_from,p_to,w)x),
 tax AS MATERIALIZED(SELECT * FROM accounting.bas_full_tax_events WHERE company_id=core.current_company() AND attribution_date>=p_from AND attribution_date<p_to),
 sale_totals AS MATERIALIZED(SELECT worksheet,coalesce(sum(gross_amount)FILTER(WHERE classification<>'EXCLUDED'),0)AS g1,coalesce(sum(gross_amount)FILTER(WHERE classification='EXPORT'),0)AS g2,coalesce(sum(gross_amount)FILTER(WHERE classification='OTHER_GST_FREE'),0)AS g3,coalesce(sum(gross_amount)FILTER(WHERE classification='INPUT_TAXED'),0)AS g4,count(*)FILTER(WHERE classification='PENDING')AS errors FROM sales GROUP BY worksheet),
 purchase_totals AS MATERIALIZED(SELECT worksheet,coalesce(sum(gross_amount)FILTER(WHERE purchase_class='CAPITAL'),0)AS g10,coalesce(sum(gross_amount)FILTER(WHERE purchase_class='NON_CAPITAL'),0)AS g11,coalesce(sum(g13)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g13,coalesce(sum(g14)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g14,coalesce(sum(g15)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g15,count(*)FILTER(WHERE issue)AS errors FROM purchases GROUP BY worksheet),
 totals AS MATERIALIZED(SELECT w AS worksheet,coalesce(s.g1,0)AS g1,coalesce(s.g2,0)AS g2,coalesce(s.g3,0)AS g3,coalesce(s.g4,0)AS g4,coalesce(p.g10,0)AS g10,coalesce(p.g11,0)AS g11,coalesce(p.g13,0)AS g13,coalesce(p.g14,0)AS g14,coalesce(p.g15,0)AS g15,coalesce(s.errors,0)+coalesce(p.errors,0)AS errors FROM(VALUES(false),(true))v(w)LEFT JOIN sale_totals s ON s.worksheet=w LEFT JOIN purchase_totals p ON p.worksheet=w),
 purchase_control AS(SELECT accounting.bas_purchase_reference(p_from,p_to)AS expected,coalesce((SELECT sum(gross_amount) FROM purchases WHERE NOT worksheet),0)AS actual,coalesce((SELECT sum(gross_amount) FROM purchases WHERE NOT worksheet AND purchase_class='EXCLUDED'),0)AS excluded),
 tax_totals AS(SELECT coalesce(sum(CASE WHEN side='SALES' THEN gst_amount ELSE -gst_amount END)FILTER(WHERE legal_adjustment),0)AS adjustment_net,coalesce(sum(gst_amount)FILTER(WHERE side='SALES' AND NOT legal_adjustment),0)AS base_sales_tax,coalesce(sum(gst_amount)FILTER(WHERE side='PURCHASES' AND NOT legal_adjustment),0)AS base_purchase_tax FROM tax),
 computed AS(SELECT t.*,g2+g3+g4 AS g5,g1-g2-g3-g4 AS g6,g10+g11 AS g12,g13+g14+g15 AS g16,g10+g11-g13-g14-g15 AS g17,greatest(adjustment_net,0)*11 AS g7,greatest(-adjustment_net,0)*11 AS g18,x.* FROM totals t CROSS JOIN tax_totals x WHERE worksheet),
 sheet AS MATERIALIZED(SELECT *,g6+g7 AS g8,round((g6+g7)/11,2)AS g9,g17+g18 AS g19,round((g17+g18)/11,2)AS g20,round(g6/11,2)-base_sales_tax AS sales_difference,round(g17/11,2)-base_purchase_tax AS purchase_difference FROM computed),
 assessed AS(SELECT b.report,a.*,w.g9,w.g20,w.sales_difference,w.purchase_difference,w.errors AS sheet_errors,pc.expected AS purchase_reference_gross,pc.actual AS purchase_sources_gross,pc.excluded AS excluded_purchase_gross,
 (CASE WHEN b.report->>'status'='UNRECONCILED' OR pc.actual<>pc.expected OR a.g1<>(b.report->'financial'->>'G1')::numeric THEN 'UNRECONCILED' WHEN a.errors+w.errors>0 THEN 'INCOMPLETE' WHEN (p_method='WORKSHEET' AND(abs(w.sales_difference)>0.01 OR abs(w.purchase_difference)>0.01 OR w.g1<0 OR w.g2<0 OR w.g3<0 OR w.g10<0 OR w.g11<0 OR w.g9<0 OR w.g20<0)) OR(p_method='ACCOUNTS' AND(b.report->>'status'='REVIEW_REQUIRED' OR a.g2<0 OR a.g3<0 OR a.g10<0 OR a.g11<0)) THEN 'REVIEW_REQUIRED' ELSE 'READY' END)AS full_status
 FROM base b CROSS JOIN totals a CROSS JOIN sheet w CROSS JOIN purchase_control pc WHERE NOT a.worksheet),
 worksheet_json AS(SELECT jsonb_build_object('G1',g1::text,'G2',g2::text,'G3',g3::text,'G4',g4::text,'G5',g5::text,'G6',g6::text,'G7',g7::text,'G8',g8::text,'G9',g9::text,'G10',g10::text,'G11',g11::text,'G12',g12::text,'G13',g13::text,'G14',g14::text,'G15',g15::text,'G16',g16::text,'G17',g17::text,'G18',g18::text,'G19',g19::text,'G20',g20::text,'adjustmentNetGst',adjustment_net::text,'baseSalesGst',base_sales_tax::text,'basePurchaseGst',base_purchase_tax::text,'salesCalculationDifference',sales_difference::text,'purchaseCalculationDifference',purchase_difference::text,'netCalculationDifference',(g9-g20-(base_sales_tax-base_purchase_tax+adjustment_net))::text,'status',CASE WHEN errors>0 THEN 'INCOMPLETE' WHEN abs(sales_difference)>0.01 OR abs(purchase_difference)>0.01 OR least(g1,g2,g3,g10,g11,g9,g20)<0 THEN 'REVIEW_REQUIRED' ELSE 'READY' END)AS value FROM sheet)
 SELECT a.report||jsonb_build_object('method','FULL_'||p_method,'reportingMethod','FULL','calculationMethod',p_method,'status',a.full_status,
 'financial',(a.report->'financial')||jsonb_build_object('full',jsonb_build_object('G1',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G1' ELSE a.g1::text END,'G2',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G2' ELSE a.g2::text END,'G3',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G3' ELSE a.g3::text END,'G4',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G4' ELSE a.g4::text END,'G10',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G10' ELSE a.g10::text END,'G11',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G11' ELSE a.g11::text END,'1A',CASE WHEN p_method='WORKSHEET' THEN a.g9::text ELSE a.report->'financial'->>'1A' END,'1B',CASE WHEN p_method='WORKSHEET' THEN a.g20::text ELSE a.report->'financial'->>'1B' END,'netGst',CASE WHEN p_method='WORKSHEET' THEN(a.g9-a.g20)::text ELSE a.report->'financial'->>'netGst' END,'classificationIssueCount',a.errors+a.sheet_errors,'purchaseReferenceGross',a.purchase_reference_gross::text,'purchaseSourcesGross',a.purchase_sources_gross::text,'excludedPurchaseGross',a.excluded_purchase_gross::text,'purchaseGrossDifference',(a.purchase_sources_gross-a.purchase_reference_gross)::text,'salesGrossDifference',(a.g1-(a.report->'financial'->>'G1')::numeric)::text,'worksheet',w.value)),
 'wholeDollarLabels',(SELECT jsonb_object_agg(key,trunc(value::numeric)::text) FROM jsonb_each_text(jsonb_build_object('G1',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G1' ELSE a.g1::text END,'G2',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G2' ELSE a.g2::text END,'G3',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G3' ELSE a.g3::text END,'G10',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G10' ELSE a.g10::text END,'G11',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G11' ELSE a.g11::text END,'1A',CASE WHEN p_method='WORKSHEET' THEN a.g9::text ELSE a.report->'financial'->>'1A' END,'1B',CASE WHEN p_method='WORKSHEET' THEN a.g20::text ELSE a.report->'financial'->>'1B' END))),
 'worksheet',w.value,'classificationIssues',coalesce((SELECT jsonb_agg(row ORDER BY source_type,source_id) FROM(SELECT source_type,source_id,jsonb_build_object('side','SALES','sourceType',source_type,'sourceId',source_id,'sourceDocumentId',source_document_id,'taxCodeId',tax_code_id,'classification',classification)AS row FROM sales WHERE classification='PENDING' AND NOT worksheet UNION ALL SELECT source_type,source_id,jsonb_build_object('side','PURCHASES','sourceType',source_type,'sourceId',source_id,'sourceDocumentId',source_document_id,'billLineId',bill_line_id,'classification',purchase_class)FROM purchases WHERE issue AND NOT worksheet)x),'[]'::jsonb))FROM assessed a CROSS JOIN worksheet_json w
 $$;
CREATE FUNCTION accounting.bas_full_summary(p_from date,p_to date,p_method text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH x AS MATERIALIZED(SELECT accounting.bas_full_summary_raw(p_from,p_to,p_method)AS body)
 SELECT body||jsonb_build_object('wholeDollarLabels',(body->'wholeDollarLabels')||jsonb_build_object('netGst',((body->'wholeDollarLabels'->>'1A')::numeric-(body->'wholeDollarLabels'->>'1B')::numeric)::text,'roundingDifference',((body->'wholeDollarLabels'->>'1A')::numeric-(body->'wholeDollarLabels'->>'1B')::numeric-(body->'financial'->'full'->>'netGst')::numeric)::text))FROM x
 $$;
CREATE FUNCTION accounting.bas_report(p_from date,p_to date,p_reporting text,p_calculation text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN
 IF p_reporting='SIMPLER' AND p_calculation='ACCOUNTS' THEN RETURN accounting.bas_summary(p_from,p_to);ELSIF p_reporting='FULL' AND p_calculation IN('ACCOUNTS','WORKSHEET') THEN RETURN accounting.bas_full_summary(p_from,p_to,p_calculation);END IF;RAISE EXCEPTION 'Unsupported BAS reporting/calculation method' USING ERRCODE='HR422';END $$;
CREATE FUNCTION accounting.bas_report_sources(p_from date,p_to date,p_reporting text,p_calculation text) RETURNS TABLE(source_type text,source_id uuid,payload jsonb)LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT * FROM accounting.bas_source_items(p_from,p_to)
 UNION ALL SELECT 'FULL_SALES_'||CASE WHEN w THEN 'WORKSHEET_' ELSE 'ACCOUNTS_' END||x.source_type,x.source_id,to_jsonb(x)||jsonb_build_object('gross_amount',x.gross_amount::text,'sales_class',accounting.bas_sales_class(x.tax_code_id),'classification_id',(SELECT id FROM accounting.bas_latest_classifications WHERE company_id=x.company_id AND target_kind='TAX_CODE' AND target_id=x.tax_code_id),'classification_revision',coalesce((SELECT revision FROM accounting.bas_latest_classifications WHERE company_id=x.company_id AND target_kind='TAX_CODE' AND target_id=x.tax_code_id),0),'worksheet',w)FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_sales(p_from,p_to,w)x WHERE p_reporting='FULL'
 UNION ALL SELECT 'FULL_PURCHASE_'||CASE WHEN w THEN 'WORKSHEET_' ELSE 'ACCOUNTS_' END||x.source_type,x.source_id,to_jsonb(x)||jsonb_build_object('gross_amount',x.gross_amount::text,'g13',x.g13::text,'g14',x.g14::text,'g15',x.g15::text,'worksheet',w)FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_purchase_items(p_from,p_to,w)x WHERE p_reporting='FULL'
 $$;
CREATE FUNCTION accounting.create_bas_period_full(p_reference text,p_from date,p_to date,p_cadence text,p_basis text,p_method text,p_registered boolean,p_due date,p_calculation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();v uuid:=gen_random_uuid();BEGIN
 PERFORM accounting.bas_require_access('accounting.bas.manage');PERFORM accounting.bas_lock(c,true);
 IF p_from IS NULL OR p_to IS NULL OR p_from<'0002-01-01' OR p_to<=p_from OR p_to-p_from>366 OR p_registered IS DISTINCT FROM true OR (p_method IS NULL OR p_method NOT IN('SIMPLER','FULL') OR p_calculation IS NULL OR p_calculation NOT IN('ACCOUNTS','WORKSHEET') OR(p_method='SIMPLER' AND p_calculation<>'ACCOUNTS')) OR p_basis NOT IN('CASH','NON_CASH') OR p_basis IS NULL OR p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_due<p_to THEN RAISE EXCEPTION 'Invalid BAS period or explicit registration/method confirmation missing' USING ERRCODE='HR422';END IF;
 IF p_cadence IS NULL OR p_cadence NOT IN('MONTHLY','QUARTERLY','ANNUAL','CUSTOM') OR(p_cadence<>'CUSTOM' AND(extract(day FROM p_from)<>1 OR(p_cadence='MONTHLY' AND p_to<>(p_from+interval '1 month')::date) OR(p_cadence='QUARTERLY' AND(extract(month FROM p_from)::int NOT IN(1,4,7,10) OR p_to<>(p_from+interval '3 month')::date)) OR(p_cadence='ANNUAL' AND(extract(month FROM p_from)<>7 OR p_to<>(p_from+interval '1 year')::date)))) THEN RAISE EXCEPTION 'Invalid BAS cadence' USING ERRCODE='HR422';END IF;
 IF NOT EXISTS(SELECT 1 FROM core.companies WHERE id=c AND abn IS NOT NULL AND length(abn)=11) THEN RAISE EXCEPTION 'Company ABN required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_periods WHERE company_id=c AND from_date<p_to AND to_date>p_from) THEN RAISE EXCEPTION 'BAS periods overlap' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bas_periods(id,company_id,reference,from_date,to_date,cadence,gst_basis,reporting_method,registration_confirmed,due_on,created_by,calculation_method) VALUES(v,c,btrim(p_reference),p_from,p_to,p_cadence,p_basis,p_method,true,p_due,core.current_actor(),p_calculation);
 INSERT INTO accounting.bas_period_controls(id,company_id) VALUES(v,c);RETURN v;END $$;
CREATE OR REPLACE FUNCTION accounting.create_bas_period(p_reference text,p_from date,p_to date,p_cadence text,p_basis text,p_method text,p_registered boolean,p_due date) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT accounting.create_bas_period_full(p_reference,p_from,p_to,p_cadence,p_basis,p_method,p_registered,p_due,'ACCOUNTS')$$;
CREATE OR REPLACE FUNCTION accounting.bas_transition(p_id uuid,p_version bigint,p_action text,p_reference text,p_reason text,p_lodged date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();p accounting.bas_periods;k accounting.bas_period_controls;s uuid;report jsonb;rev bigint;today date;BEGIN
 IF p_action NOT IN('FINALIZED','REOPENED','LODGED') OR p_action IS NULL THEN RAISE EXCEPTION 'Invalid BAS action' USING ERRCODE='HR422';END IF;
 PERFORM accounting.bas_require_access(CASE p_action WHEN 'FINALIZED' THEN 'accounting.bas.finalize' WHEN 'REOPENED' THEN 'accounting.bas.reopen' ELSE 'accounting.bas.lodged' END);PERFORM accounting.bas_lock(c,true);
 SELECT * INTO p FROM accounting.bas_effective_periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'BAS period unavailable' USING ERRCODE='HT404';END IF;
 SELECT * INTO k FROM accounting.bas_period_controls WHERE company_id=c AND id=p_id FOR UPDATE;IF k.version<>p_version OR p_version IS NULL THEN RAISE EXCEPTION 'BAS version changed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and reason required' USING ERRCODE='HR422';END IF;
 SELECT (now() AT TIME ZONE timezone)::date INTO today FROM core.companies WHERE id=c;
 s:=k.current_snapshot_id;
 IF p_action='FINALIZED' THEN
 IF k.state<>'OPEN' THEN RAISE EXCEPTION 'BAS period is not open' USING ERRCODE='HR409';END IF;
 IF p.to_date>today+1 THEN RAISE EXCEPTION 'Future BAS period cannot be finalized' USING ERRCODE='HR422';END IF;
 report:=accounting.bas_report(p.from_date,p.to_date,p.reporting_method,p.calculation_method)||jsonb_build_object('periodId',p.id,'declaredBasis',p.gst_basis,'registrationConfirmed',p.registration_confirmed,'amendsSnapshotId',(SELECT e.snapshot_id FROM accounting.bas_period_events e WHERE e.company_id=c AND e.period_id=p.id AND e.action='LODGED' ORDER BY e.created_at DESC,e.id DESC LIMIT 1));IF report->>'status'<>'READY' THEN RAISE EXCEPTION 'BAS requires financial review or ledger reconciliation' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(revision),0)+1 INTO rev FROM accounting.bas_snapshots WHERE company_id=c AND period_id=p_id;
 s:=gen_random_uuid();
 INSERT INTO accounting.bas_snapshots(id,company_id,period_id,revision,report,financial_hash,source_hash,reason,created_by) SELECT s,c,p_id,rev,report,accounting.bas_financial_hash(report),encode(sha256(convert_to(coalesce(string_agg(source_type||source_id::text||payload::text,'|' ORDER BY source_type,source_id),''),'UTF8')),'hex'),btrim(p_reason),core.current_actor() FROM accounting.bas_report_sources(p.from_date,p.to_date,p.reporting_method,p.calculation_method);
 INSERT INTO accounting.bas_snapshot_items SELECT c,s,source_type,source_id,payload FROM accounting.bas_report_sources(p.from_date,p.to_date,p.reporting_method,p.calculation_method);
 ELSIF p_action='REOPENED' THEN
 IF k.state NOT IN('FINALIZED','LODGED') THEN RAISE EXCEPTION 'BAS period is already open' USING ERRCODE='HR409';END IF;
 ELSE
 IF k.state<>'FINALIZED' THEN RAISE EXCEPTION 'Finalize BAS before recording lodgement' USING ERRCODE='HR409';END IF;
 IF p_lodged IS NULL OR p_lodged<p.to_date-1 OR p_lodged>today THEN RAISE EXCEPTION 'Invalid lodgement date' USING ERRCODE='HR422';END IF;
 END IF;
 INSERT INTO accounting.bas_period_events(company_id,period_id,snapshot_id,action,reference,reason,lodged_on,created_by) VALUES(c,p_id,s,p_action,btrim(p_reference),btrim(p_reason),CASE WHEN p_action='LODGED' THEN p_lodged END,core.current_actor());
 UPDATE accounting.bas_period_controls SET state=CASE p_action WHEN 'REOPENED' THEN 'OPEN' ELSE p_action END,current_snapshot_id=s WHERE company_id=c AND id=p_id;RETURN s;END $$;
CREATE OR REPLACE FUNCTION accounting.bas_check_frozen() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid;p record;token text;cache text;BEGIN
 c:=CASE WHEN TG_TABLE_SCHEMA='core' AND TG_TABLE_NAME='companies' THEN coalesce(NEW.id,OLD.id) ELSE coalesce((to_jsonb(NEW)->>'company_id')::uuid,(to_jsonb(OLD)->>'company_id')::uuid) END;
 IF c IS DISTINCT FROM core.current_company() THEN RAISE EXCEPTION 'BAS company context mismatch' USING ERRCODE='HR409';END IF;
 token:=coalesce(current_setting('htt.bas_dirty',true),'');cache:='htt.bas_checked_'||replace(c::text,'-','');IF current_setting(cache,true)=token THEN RETURN NULL;END IF;
 FOR p IN SELECT b.from_date,b.to_date,s.financial_hash,b.reporting_method,b.calculation_method FROM accounting.bas_period_controls k JOIN accounting.bas_effective_periods b ON b.company_id=k.company_id AND b.id=k.id JOIN accounting.bas_snapshots s ON s.company_id=k.company_id AND s.id=k.current_snapshot_id WHERE k.company_id=c AND k.state IN('FINALIZED','LODGED') LOOP
 IF accounting.bas_financial_hash(accounting.bas_report(p.from_date,p.to_date,p.reporting_method,p.calculation_method))<>p.financial_hash THEN RAISE EXCEPTION 'Reopen BAS period before changing frozen financial totals or tax ledger' USING ERRCODE='HR409';END IF;END LOOP;
 PERFORM set_config(cache,token,true);RETURN NULL;END $$;
CREATE TRIGGER bas_dirty BEFORE INSERT OR UPDATE OR DELETE ON accounting.bas_classifications FOR EACH STATEMENT EXECUTE FUNCTION accounting.bas_dirty();
CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON accounting.bas_classifications FOR EACH ROW EXECUTE FUNCTION accounting.bas_write_lock();
CREATE CONSTRAINT TRIGGER bas_frozen AFTER INSERT OR UPDATE OR DELETE ON accounting.bas_classifications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.bas_check_frozen();
CREATE TRIGGER bas_dirty BEFORE INSERT OR UPDATE OR DELETE ON purchase.bill_lines FOR EACH STATEMENT EXECUTE FUNCTION accounting.bas_dirty();
CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON purchase.bill_lines FOR EACH ROW EXECUTE FUNCTION accounting.bas_write_lock();
CREATE CONSTRAINT TRIGGER bas_frozen AFTER INSERT OR UPDATE OR DELETE ON purchase.bill_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.bas_check_frozen();
CREATE TRIGGER bas_dirty BEFORE INSERT OR UPDATE OR DELETE ON purchase.bills FOR EACH STATEMENT EXECUTE FUNCTION accounting.bas_dirty();
CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON purchase.bills FOR EACH ROW EXECUTE FUNCTION accounting.bas_write_lock();
CREATE CONSTRAINT TRIGGER bas_frozen AFTER INSERT OR UPDATE OR DELETE ON purchase.bills DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.bas_check_frozen();
